const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 1) {
    n = lines[0] - 0;
  }

  if (n && lines.length === n + 1) {
    const ranges = lines.slice(1).map((line) => line.split(" ").map(Number));
    console.log(getResult(ranges));
    lines.length = 0;
  }
});

function getResult(ranges) {
  // 由于题目并未说有几个站点，因此需要计算出最后一个站点
  const last = Math.max.apply(null, ranges.toString().split(",").map(Number));

  // 如果存在 [3,2] 这种坐车区间，即从站点3 -> 站点4 -> 站点1 -> 站点2，则此时将该坐车区间拆分为 [3, 4]和[1, 2]
  const tmp = [];
  ranges.forEach((range) => {
    const [s, e] = range;

    if (s > e) {
      // 拆分
      tmp.push([s, last]);
      tmp.push([1, e]);
    } else {
      tmp.push(range);
    }
  });
  ranges = tmp;

  // 最大重叠区间个数求解
  ranges.sort((a, b) => a[0] - b[0]);
  const end = new PriorityQueue((a, b) => b - a);

  let max = 0;
  let ans = ranges[0][0];
  for (let range of ranges) {
    const [s, e] = range;

    while (end.size()) {
      const top = end.peek();

      if (top < s) {
        end.shift();
      } else {
        break;
      }
    }

    end.push(e);

    if (end.size() > max) {
      max = end.size();
      ans = s;
    }
  }

  return ans;
}

class PriorityQueue {
  constructor(cpr) {
    this.queue = [];
    this.cpr = cpr;
  }

  swap(a, b) {
    const tmp = this.queue[a];
    this.queue[a] = this.queue[b];
    this.queue[b] = tmp;
  }

  // 上浮
  swim() {
    let c = this.queue.length - 1;

    while (c >= 1) {
      const f = Math.floor((c - 1) / 2);

      if (this.cpr(this.queue[c], this.queue[f]) > 0) {
        this.swap(c, f);
        c = f;
      } else {
        break;
      }
    }
  }

  // 入队
  push(val) {
    this.queue.push(val);
    this.swim();
  }

  // 下沉
  sink() {
    let f = 0;

    while (true) {
      let c1 = 2 * f + 1;
      let c2 = c1 + 1;

      let c;
      let val1 = this.queue[c1];
      let val2 = this.queue[c2];
      if (val1 && val2) {
        c = this.cpr(val1, val2) > 0 ? c1 : c2;
      } else if (val1 && !val2) {
        c = c1;
      } else if (!val1 && val2) {
        c = c2;
      } else {
        break;
      }

      if (this.cpr(this.queue[c], this.queue[f]) > 0) {
        this.swap(c, f);
        f = c;
      } else {
        break;
      }
    }
  }

  // 出队
  shift() {
    this.swap(0, this.queue.length - 1);
    const res = this.queue.pop();
    this.sink();
    return res;
  }

  // 查看顶
  peek() {
    return this.queue[0];
  }

  size() {
    return this.queue.length;
  }
}

